#include <juce_dsp/juce_dsp.h>
#include "AnamorphEngine.h"
#include <cstdio>
#include <cmath>
#include <memory>
static void run(anamorph::AnamorphEngine& e, anamorph::EngineParameters p,juce::AudioBuffer<float>& b,int t){for(int i=0;i<b.getNumSamples();++i){float x=float(t+i);b.setSample(0,i,.42f*std::sin(.137f*x)+.19f*std::cos(.037f*x));b.setSample(1,i,.11f*std::cos(.091f*x)-.24f*std::sin(.057f*x));}e.setParameters(p);e.process(b);}
int main(){juce::ScopedNoDenormals d;for(double sr:{44100.,48000.})for(int kind:{0,1})for(int initialOn:{0,1})for(int phase:{0,1}){constexpr int n=64;anamorph::EngineParameters p;p.algorithm=anamorph::Algorithm::Haas;p.algoAmount=.65f;p.width=1.8f;p.mbWidthLow=.2f;p.mbWidthMid=1.8f;p.mbWidthHiMid=.35f;p.mbWidthHigh=1.7f;if(kind==0)p.bypass=initialOn;else p.mbEnable=initialOn;auto a=std::make_unique<anamorph::AnamorphEngine>(),b=std::make_unique<anamorph::AnamorphEngine>(),c=std::make_unique<anamorph::AnamorphEngine>(),z=std::make_unique<anamorph::AnamorphEngine>();for(auto*e:{a.get(),b.get(),c.get(),z.get()}){e->primeParameters(p);e->prepare(sr,n);}juce::AudioBuffer<float>aa(2,n),bb(2,n),cc(2,n),zz(2,n);int t=0;for(int k=0;k<30;++k,t+=n){run(*a,p,aa,t);run(*b,p,bb,t);run(*c,p,cc,t);run(*z,p,zz,t);}int ab=0,cz=0;double peak=0,cp=0;for(int k=0;k<36;++k,t+=n){auto x=p,y=p,w=p,q=p;x.algorithm=y.algorithm=anamorph::Algorithm::Velvet;bool event=(phase==0?k>=1&&k<4:k>=8&&k<16);if(kind==0){x.bypass=w.bypass=event?!initialOn:initialOn;}else{x.mbEnable=w.mbEnable=event?!initialOn:initialOn;}run(*a,x,aa,t);run(*b,y,bb,t);run(*c,w,cc,t);run(*z,q,zz,t);for(int ch=0;ch<2;++ch)for(int i=0;i<n;++i){double u=std::abs((double)aa.getSample(ch,i)-bb.getSample(ch,i)),v=std::abs((double)cc.getSample(ch,i)-zz.getSample(ch,i));ab+=u!=0;cz+=v!=0;if(u>peak)peak=u;if(v>cp)cp=v;}}std::printf("rate=%.0f control=%s initial=%d pulse=%s duck_diffs=%d peak=%.8g normal_diffs=%d peak=%.8g\n",sr,kind?"MB":"bypass",initialOn,phase?"in":"out",ab,peak,cz,cp);}}
